package io.github.diodeme.ji.artifact;

import java.time.Duration;
import java.util.Objects;

/** Configurable artifact limits; defaults are the Stage 2 product contract. */
public record ArtifactLimits(
        long directUploadBytes,
        long chunkBytes,
        long objectBytes,
        long hostQuotaBytes,
        int warningPercent,
        Duration incompleteUploadTtl,
        Duration orphanGrace) {
    public static final long MIB = 1024L * 1024L;
    public static final long GIB = 1024L * MIB;

    public ArtifactLimits {
        if (directUploadBytes <= 0 || chunkBytes <= 0 || objectBytes <= 0 || hostQuotaBytes <= 0) {
            throw new IllegalArgumentException("artifact limits must be positive");
        }
        if (directUploadBytes > objectBytes || chunkBytes > objectBytes || objectBytes > hostQuotaBytes) {
            throw new IllegalArgumentException("artifact size limits must be ordered");
        }
        if (warningPercent <= 0 || warningPercent >= 100) throw new IllegalArgumentException("warningPercent must be between 1 and 99");
        Objects.requireNonNull(incompleteUploadTtl, "incompleteUploadTtl");
        Objects.requireNonNull(orphanGrace, "orphanGrace");
        if (incompleteUploadTtl.isNegative() || incompleteUploadTtl.isZero() || orphanGrace.isNegative() || orphanGrace.isZero()) {
            throw new IllegalArgumentException("retention durations must be positive");
        }
    }

    public static ArtifactLimits defaults() {
        return new ArtifactLimits(8 * MIB, 8 * MIB, 2 * GIB, 20 * GIB, 80,
                Duration.ofHours(24), Duration.ofDays(7));
    }
}
